<script lang="ts">
 import {onDestroy,untrack} from 'svelte';import {Session} from '$lib/stores';
 import {createNativeTeamController,type NativeTeamController,type OwnGroup,type TeamRequest} from './native-team-client';
 import {nativeAccountIssue,type NativeAccountIssue} from './native-account-scope';import AccountActionGate from './AccountActionGate.svelte';
 let owner=$state.raw<NativeTeamController>(),groups=$state<OwnGroup[]>([]),requests=$state<TeamRequest[]>([]),busy=$state(false),message=$state(''),issue=$state<NativeAccountIssue>(),more=$state(false);let disposed=false,epoch=0;
 onDestroy(()=>{disposed=true;epoch++;owner?.dispose();});
 async function initialize(){const session=$Session,token=++epoch;owner?.dispose();owner=undefined;groups=[];requests=[];message='';issue=undefined;more=false;busy=true;if(!session?.identity?.id){busy=false;return;}const check=()=>{if(disposed||epoch!==token||session!==$Session)throw Error('The account changed.');};try{const next=await createNativeTeamController(session.identity.id,check);check();owner=next;const mine=await next.ownGroups();check();groups=mine.data;more=mine.hasMore;const inbox=await next.inbox();check();requests=inbox.data;more=more||inbox.hasMore;}catch(e){if(!disposed&&epoch===token){issue=nativeAccountIssue(e);message=e instanceof Error?e.message:'Could not load your teams.';}}finally{if(!disposed&&epoch===token)busy=false;}}
 $effect(()=>{const session=$Session;untrack(()=>{void session;void initialize();});});
</script>
<svelte:head><title>My teams</title></svelte:head>
<section class="mx-auto max-w-270 space-y-4 p-5"><h1 class="text-xl font-medium">My teams</h1><p>Create a group, review invitations, or open a team to manage its members.</p><nav class="flex flex-wrap gap-3"><a class="underline" href="/catalogue-tools?kind=group">Create group</a><a class="underline" href="/groups">Find a group</a></nav><AccountActionGate {issue} onready={initialize} />{#if message}<p role="status">{message}</p>{/if}
 <h2 class="font-medium">Your groups</h2>{#if !busy&&!groups.length}<p>You have not joined a group yet.</p>{/if}<ul>{#each groups as group}<li><a class="underline" href={`/group/${group.id}`}>{group.name}</a> — {group.role}</li>{/each}</ul>
 <h2 class="font-medium">Invitations and join requests</h2>{#if !busy&&!requests.length}<p>No pending invitations or join requests.</p>{/if}<ul class="space-y-3">{#each requests as request}<li class="rounded border p-3"><a class="underline" href={`/group/${request.groupId}`}>{request.groupName}</a> — {request.kind==='invitation'?'Invitation waiting for your reply':'Your join request is waiting for the leader'}{#if request.message}<p>{request.message}</p>{/if}<p>Expires <time datetime={request.expiresAt}>{new Date(request.expiresAt).toLocaleString()}</time></p><a class="underline" href={`/group/${request.groupId}#team`}>Review request</a></li>{/each}</ul>{#if more}<p>Showing up to 100 groups or requests. Use Find a group to open another team.</p>{/if}<button class="rounded border px-3 py-2" disabled={busy} onclick={initialize}>Refresh my teams</button>
</section>
